	"strconv"
	"strings"
)

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	if len(f) == 0 { // 空输入直接返回
		return
	}
	p := 0
	n, _ := strconv.Atoi(f[p])
	p++
	sum, mx := 0, 0
	for i := 0; i < n; i++ {
		v, _ := strconv.Atoi(f[p])
		p++
		sum += v
		if i == 0 || v > mx {
			mx = v
		}
	}
	fmt.Println(sum, mx)
}

