import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	m, _ := strconv.Atoi(f[0])
	n, _ := strconv.Atoi(f[1])
	grid := make([]string, m)
	for i := 0; i < m; i++ {
		grid[i] = f[2+i] // 每行一个字符串
	}

	seen := make([][]bool, m)
	for i := range seen {
		seen[i] = make([]bool, n)
	}
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	blocks := 0
	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			if grid[i][j] != '1' || seen[i][j] {
				continue
			}
			blocks++
			seen[i][j] = true
			q := [][2]int{{i, j}}
			for len(q) > 0 {
				cur := q[0]
				q = q[1:]
				for _, d := range dirs {
					x, y := cur[0]+d[0], cur[1]+d[1]
					if x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == '1' && !seen[x][y] {
						seen[x][y] = true
						q = append(q, [2]int{x, y})
					}
				}
			}
		}
	}
	fmt.Println(blocks)
}

