package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type ListNode struct {
	Val  int
	Next *ListNode
}

func build(vals []int) *ListNode { // 哨兵节点尾插建表
	dummy := &ListNode{}
	cur := dummy
	for _, v := range vals {
		cur.Next = &ListNode{Val: v}
		cur = cur.Next
	}
	return dummy.Next
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	n, _ := strconv.Atoi(f[0])
	vals := make([]int, n)
	for i := 0; i < n; i++ {
		vals[i], _ = strconv.Atoi(f[1+i])
	}
	head := build(vals)

	var prev *ListNode
	for head != nil {
		nxt := head.Next
		head.Next = prev
		prev = head
		head = nxt
	}

	out := make([]string, 0, n)
	for prev != nil {
		out = append(out, strconv.Itoa(prev.Val))
		prev = prev.Next
	}
	fmt.Println(strings.Join(out, " "))
}

