package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func build(tokens []string) *TreeNode { // 层序 token，"null" 表示空
	if len(tokens) == 0 || tokens[0] == "null" {
		return nil
	}
	v, _ := strconv.Atoi(tokens[0])
	root := &TreeNode{Val: v}
	q := []*TreeNode{root}
	i := 1
	for len(q) > 0 && i < len(tokens) {
		node := q[0]
		q = q[1:]
		if tokens[i] != "null" {
			x, _ := strconv.Atoi(tokens[i])
			node.Left = &TreeNode{Val: x}
			q = append(q, node.Left)
		}
		i++
		if i < len(tokens) && tokens[i] != "null" {
			x, _ := strconv.Atoi(tokens[i])
			node.Right = &TreeNode{Val: x}
			q = append(q, node.Right)
		}
		i++
	}
	return root
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	tokens := []string{}
	if len(f) > 1 {
		tokens = f[1:] // 第一个是 n，后面是层序值
	}
	root := build(tokens)

	out := []string{}
	var dfs func(node *TreeNode)
	dfs = func(node *TreeNode) {
		if node == nil {
			return
		}
		dfs(node.Left)
		out = append(out, strconv.Itoa(node.Val))
		dfs(node.Right)
	}
	dfs(root)
	fmt.Println(strings.Join(out, " "))
}

