package main

import (
	"container/heap"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

type edge struct {
	to, w int
}

type item struct {
	d, u int
}

type minHeap []item

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i].d < h[j].d }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(item)) }

func (h *minHeap) Pop() any {
	old := *h
	it := old[len(old)-1]
	*h = old[:len(old)-1]
	return it
}

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	p := 0
	n, _ := strconv.Atoi(f[p])
	m, _ := strconv.Atoi(f[p+1])
	p += 2
	g := make([][]edge, n+1)
	for i := 0; i < m; i++ {
		u, _ := strconv.Atoi(f[p])
		v, _ := strconv.Atoi(f[p+1])
		w, _ := strconv.Atoi(f[p+2])
		p += 3
		g[u] = append(g[u], edge{v, w})
		g[v] = append(g[v], edge{u, w})
	}

	s, _ := strconv.Atoi(f[p])
	dist := make([]int, n+1)
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[s] = 0
	h := &minHeap{{0, s}}
	heap.Init(h)
	for h.Len() > 0 {
		cur := heap.Pop(h).(item) // 堆里是 (距离, 节点)
		if cur.d > dist[cur.u] {
			continue
		}
		for _, e := range g[cur.u] {
			if cur.d+e.w < dist[e.to] {
				dist[e.to] = cur.d + e.w
				heap.Push(h, item{dist[e.to], e.to})
			}
		}
	}

	out := make([]string, n)
	for i := 1; i <= n; i++ {
		if dist[i] == math.MaxInt {
			out[i-1] = "inf"
		} else {
			out[i-1] = strconv.Itoa(dist[i])
		}
	}
	fmt.Println(strings.Join(out, " "))
}

