	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := os.ReadFile("/dev/stdin")
	f := strings.Fields(string(data))
	p := 0
	n, _ := strconv.Atoi(f[p])
	m, _ := strconv.Atoi(f[p+1])
	p += 2
	parent := make([]int, n+1)
	for i := range parent {
		parent[i] = i
	}

	find := func(x int) int { // 路径压缩写成循环
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}

	merged := 0
	for i := 0; i < m; i++ {
		u, _ := strconv.Atoi(f[p])
		v, _ := strconv.Atoi(f[p+1])
		p += 2
		ru, rv := find(u), find(v)
		if ru != rv {
			parent[ru] = rv
			merged++
		}
	}
	fmt.Println(n - merged) // 连通块个数
}

