	n, _ := strconv.Atoi(f[p])
	m, _ := strconv.Atoi(f[p+1])
	p += 2
	g := make([][]int, n+1)
	indeg := make([]int, n+1)
	for i := 0; i < m; i++ {
		u, _ := strconv.Atoi(f[p])
		v, _ := strconv.Atoi(f[p+1])
		p += 2
		g[u] = append(g[u], v)
		indeg[v]++
	}

	q := []int{}
	for i := 1; i <= n; i++ {
		if indeg[i] == 0 {
			q = append(q, i)
		}
	}
	order := []string{}
	for head := 0; head < len(q); head++ {
		u := q[head]
		order = append(order, strconv.Itoa(u))
		for _, v := range g[u] {
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	if len(order) == n {
		fmt.Println(strings.Join(order, " "))
	} else {
		fmt.Println(-1) // 出队数量不足 n 说明有环
	}
}

